import numpy as np
import astropy.units as u
from scipy.integrate import quad
from gammapy.astro.darkmatter import profiles

D = 8.33 * u.kpc

def radial_ref(theta, profile, squared, D):
    """Reference for the preserved truncation: 2*[b,D] + [D,4D] for theta<=90,
    [D,4D] for theta>90, all with Jacobian r/sqrt(r^2-b^2)."""
    theta = float(u.Quantity(theta, u.rad).to_value(u.rad))
    exp = 2 if squared else 1
    Dv = D.to_value(u.kpc)
    b = Dv*np.sin(theta)
    def f(r):
        rho = profile(r*u.kpc).to_value(u.Unit('GeV cm-3'))
        return rho**exp * r/np.sqrt(r**2-b**2)
    if b > 0:
        if theta <= np.pi/2:
            q1,_ = quad(f, b, Dv, epsabs=0, epsrel=1e-11, limit=400, points=[b, Dv])
            q2,_ = quad(f, Dv, 4*Dv, epsabs=0, epsrel=1e-11, limit=400, points=[Dv])
            q = 2*q1+q2
        else:
            q,_ = quad(f, Dv, 4*Dv, epsabs=0, epsrel=1e-11, limit=400, points=[Dv])
    else:
        if theta <= np.pi/2:
            def g(r):
                rho = profile(r*u.kpc).to_value(u.Unit('GeV cm-3'))
                return rho**exp
            q1,_ = quad(g, 0, Dv, epsabs=0, epsrel=1e-11, limit=400)
            q2,_ = quad(g, Dv, 4*Dv, epsabs=0, epsrel=1e-11, limit=400)
            q = 2*q1+q2
        else:
            def g(r):
                rho = profile(r*u.kpc).to_value(u.Unit('GeV cm-3'))
                return rho**exp
            q,_ = quad(g, Dv, 4*Dv, epsabs=0, epsrel=1e-11, limit=400)
    return q * (u.kpc.to(u.cm) if exp==2 else u.kpc.to(u.cm))

def new_val(theta, profile, squared, D, ndecade=300):
    rmin = (D*np.sin(theta)).to(D.unit)
    rmax = D
    if theta <= np.pi/2:
        near = 2*profile.integral(rmin, rmax, theta, ndecade, squared, distance=D)
    else:
        near = 0
    far = profile.integral(rmax, 4*rmax, theta, ndecade, squared, distance=D)
    val = near + far
    return val.to_value(u.Unit('GeV2 cm-5') if squared else u.Unit('GeV cm-2'))

prof_list = {
    'NFW': profiles.NFWProfile(),
    'Einasto': profiles.EinastoProfile(),
    'Burkert': profiles.BurkertProfile(),
    'Isothermal': profiles.IsothermalProfile(),
    'Moore': profiles.MooreProfile(),
    'Zhao': profiles.ZhaoProfile(),
}
for name, p in prof_list.items():
    print('==', name)
    for theta_deg in [0.1, 5, 30, 60, 89, 120, 170]:
        theta = np.radians(theta_deg)
        for sq in (True, False):
            ref = radial_ref(theta, p, sq, D)
            val = new_val(theta, p, sq, D)
            rel = abs(val-ref)/abs(ref) if ref != 0 else 0
            print(f"  theta={theta_deg:6.2f} sq={sq} ref={ref:.6e} new={val:.6e} rel={rel:.2e}")
