@staticmethod
def _simpson_rule(y, x):
    """Composite Simpson's rule on equally spaced samples.

    For an even number of samples the last interval is integrated with
    the trapezoidal rule so that no part of the domain is dropped.
    """
    n = len(x)
    if n < 2:
        return 0.0
    if n == 2:
        return 0.5 * (y[0] + y[1]) * (x[1] - x[0])
    step = x[1] - x[0]
    if n % 2 == 0:
        m = n - 1
        simpson = (
            step
            / 3.0
            * (y[0] + y[m - 1] + 4.0 * np.sum(y[1 : m - 1 : 2]) + 2.0 * np.sum(y[2 : m - 2 : 2]))
        )
        trapezoid = 0.5 * step * (y[m - 1] + y[m])
